import * as NodeFS from "node:fs";
import * as NodePath from "node:path";
import * as NodeURL from "node:url";

import { ForkError, readJson } from "./core.ts";
import { git, upstreamBase } from "./release.ts";

/**
 * The fork touches exactly two upstream files, both regenerated by code so a sync never needs a
 * hand merge: t3.json (upstream's entries + fork/t3.fork.json) and a marked block in AGENTS.md.
 */

interface T3Script {
  name: string;
  command: string;
  [key: string]: unknown;
}

interface T3File {
  scripts?: T3Script[];
  [key: string]: unknown;
}

const AGENTS_BEGIN = "<!-- t3-fork:begin -->";
const AGENTS_END = "<!-- t3-fork:end -->";
const AGENTS_BLOCK = [
  AGENTS_BEGIN,
  "",
  "## Personal fork",
  "",
  "This checkout belongs to a personal fork with a live stable instance. Read [fork/AGENTS.md](fork/AGENTS.md) before starting servers, touching T3 homes, or editing upstream files.",
  AGENTS_END,
].join("\n");

export function forkScripts(repo: string): T3Script[] {
  const file = readJson<{ scripts: T3Script[] }>(NodePath.join(repo, "fork/t3.fork.json"));
  if (!file) throw new ForkError("fork/t3.fork.json is missing or invalid JSON");
  return file.scripts;
}

/** Upstream's t3.json plus the fork's scripts; a fork script replaces an upstream one with the same name. */
export function renderT3Json(upstreamText: string, scripts: ReadonlyArray<T3Script>): string {
  const upstream = JSON.parse(upstreamText) as T3File;
  const names = new Set(scripts.map((script) => script.name.toLowerCase()));
  const kept = (upstream.scripts ?? []).filter((script) => !names.has(script.name.toLowerCase()));
  return `${JSON.stringify({ ...upstream, scripts: [...kept, ...scripts] }, null, 2)}\n`;
}

/** t3.json as it would be without the fork: taken from the upstream base commit. */
export function upstreamT3Json(repo: string): string {
  return git(repo, ["show", `${upstreamBase(repo)}:t3.json`]).stdout;
}

export function renderAgents(text: string): string {
  const start = text.indexOf(AGENTS_BEGIN);
  const end = text.indexOf(AGENTS_END);
  const base =
    start >= 0 && end > start ? text.slice(0, start) + text.slice(end + AGENTS_END.length) : text;
  return `${base.trimEnd()}\n\n${AGENTS_BLOCK}\n`;
}

/** T3 Code drops an invalid t3.json entirely, so validate with upstream's own decoder. */
export async function validateT3Json(repo: string, text: string): Promise<void> {
  const parser = NodePath.join(repo, "packages/shared/src/t3ProjectFile.ts");
  const module = (await import(NodeURL.pathToFileURL(parser).href)) as {
    parseT3ProjectFile: (contents: string) => unknown;
  };
  if (module.parseT3ProjectFile(text) === null) {
    throw new ForkError(
      "Generated t3.json does not decode with upstream's schema (T3 Code would ignore the whole file)",
    );
  }
}

export interface HookResult {
  file: string;
  changed: boolean;
}

export async function applyHooks(
  repo: string,
  options: { fromUpstream?: boolean; write: boolean },
): Promise<HookResult[]> {
  const t3Path = NodePath.join(repo, "t3.json");
  const agentsPath = NodePath.join(repo, "AGENTS.md");
  const t3Base = options.fromUpstream ? upstreamT3Json(repo) : NodeFS.readFileSync(t3Path, "utf8");
  const agentsBase = options.fromUpstream
    ? git(repo, ["show", `${upstreamBase(repo)}:AGENTS.md`]).stdout
    : NodeFS.readFileSync(agentsPath, "utf8");
  const t3 = renderT3Json(t3Base, forkScripts(repo));
  await validateT3Json(repo, t3);
  const agents = renderAgents(agentsBase);
  const results: HookResult[] = [];
  for (const [file, text] of [
    [t3Path, t3],
    [agentsPath, agents],
  ] as const) {
    const existing = NodeFS.existsSync(file) ? NodeFS.readFileSync(file, "utf8") : "";
    const changed = existing !== text;
    if (changed && options.write) NodeFS.writeFileSync(file, text);
    results.push({ file: NodePath.relative(repo, file), changed });
  }
  return results;
}

/** Resolve a conflicted hook file by taking upstream's side and re-applying the fork's part. */
export async function resolveHookConflict(
  repo: string,
  relFile: string,
  upstreamRefName: string,
): Promise<boolean> {
  if (relFile !== "t3.json" && relFile !== "AGENTS.md") return false;
  const theirs = git(repo, ["show", `${upstreamRefName}:${relFile}`]).stdout;
  const text =
    relFile === "t3.json" ? renderT3Json(theirs, forkScripts(repo)) : renderAgents(theirs);
  if (relFile === "t3.json") await validateT3Json(repo, text);
  NodeFS.writeFileSync(NodePath.join(repo, relFile), text);
  git(repo, ["add", relFile]);
  return true;
}

export interface FootprintRow {
  file: string;
  lines: number;
  budget: number | undefined;
  problem?: string;
}

export function footprint(repo: string): FootprintRow[] {
  const base = upstreamBase(repo);
  const budgets =
    readJson<Record<string, number>>(NodePath.join(repo, "fork/footprint.json")) ?? {};
  const changed = new Map<string, number>();
  const numstat = git(repo, [
    "diff",
    "--numstat",
    "--diff-filter=MDRT",
    base,
    "HEAD",
    "--",
    ".",
    ":!fork/",
  ]).stdout;
  for (const line of numstat.split("\n").filter(Boolean)) {
    const [added, removed, file] = line.split("\t");
    changed.set(file!, (Number(added) || 0) + (Number(removed) || 0));
  }
  const rows: FootprintRow[] = [];
  for (const [file, lines] of changed) {
    const budget = budgets[file];
    const problem =
      budget === undefined
        ? "upstream file edited without a budget entry (move the change into a new file, or record it with `fork footprint --write`)"
        : lines > budget
          ? `fork edits grew to ${lines} lines (budget ${budget})`
          : undefined;
    rows.push({ file, lines, budget, ...(problem ? { problem } : {}) });
  }
  for (const [file, budget] of Object.entries(budgets)) {
    if (!changed.has(file)) {
      rows.push({
        file,
        lines: 0,
        budget,
        problem: "budgeted fork hook is gone (a merge probably dropped it)",
      });
    }
  }
  return rows.sort((a, b) => a.file.localeCompare(b.file));
}

export function writeFootprint(repo: string): Record<string, number> {
  const budgets: Record<string, number> = {};
  for (const row of footprint(repo)) if (row.lines > 0) budgets[row.file] = row.lines;
  NodeFS.writeFileSync(
    NodePath.join(repo, "fork/footprint.json"),
    `${JSON.stringify(budgets, null, 2)}\n`,
  );
  return budgets;
}
